#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
// 속도는 mm/second. tick당 나눗셈의 나머지를 보존한다.
int distanceAfterOneSecond(int speed, int hz){
    int position=0, remainder=0;
    for(int i=0;i<hz;++i){
        const int numerator=remainder+speed;
        position+=numerator/hz;
        remainder=numerator%hz;
    }
    assert(remainder==0);return position;
}
int main(){
    for(int hz: {30,60,120}){
        assert(distanceAfterOneSecond(2500,hz)==2500);
        assert(distanceAfterOneSecond(1,hz)==1);
        assert(distanceAfterOneSecond(0,hz)==0);
    }
    std::cout<<"speed unit tests passed\n";
}
